import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { products } from "../data/products";

function ProductDetails() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [product, setProduct] = useState(null);
  const [selectedSize, setSelectedSize] = useState("M");
  const [selectedColor, setSelectedColor] = useState("Black");

  useEffect(() => {
    // Mock backend fetch using our static data
    const foundProduct = products.find((p) => p.id === parseInt(id));
    if (foundProduct) {
      setProduct(foundProduct);
    }
  }, [id]);

  const addToCart = () => {
    if (!product) return;

    const cartItem = {
      ...product,
      size: selectedSize,
      color: selectedColor,
      quantity: 1
    };

    let cart = JSON.parse(localStorage.getItem("cart")) || [];

    // Check if same item (with same size/color) is already in cart
    const existingIndex = cart.findIndex(item => 
      item.id === cartItem.id && 
      item.size === cartItem.size && 
      item.color === cartItem.color
    );

    if (existingIndex >= 0) {
      cart[existingIndex].quantity += 1;
    } else {
      cart.push(cartItem);
    }

    localStorage.setItem("cart", JSON.stringify(cart));
    navigate("/cart");
  };

  if (!product) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <p className="text-xl text-gray-500">Loading product...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 font-sans pb-32">
      {/* Header */}
      <header className="bg-white/80 backdrop-blur-md shadow-sm z-50 py-4 px-6 fixed w-full top-0 transition-all">
        <div className="flex justify-between items-center max-w-7xl mx-auto">
          <span 
            onClick={() => navigate("/catalog")}
            className="text-2xl font-serif italic tracking-widest cursor-pointer"
          >
            LUXE
          </span>
          <div className="flex gap-6 items-center text-sm font-medium">
            <span onClick={() => navigate("/catalog")} className="cursor-pointer hover:text-gray-500">Shop</span>
            <span onClick={() => navigate("/cart")} className="cursor-pointer hover:text-gray-500">Cart</span>
            <span onClick={() => navigate("/profile")} className="cursor-pointer hover:text-gray-500">Profile</span>
          </div>
        </div>
      </header>

      <div className="pt-24 max-w-7xl mx-auto px-6">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

          {/* IMAGE SECTION */}
          <div className="lg:col-span-7">
            <div className="aspect-[3/4] bg-gray-200 overflow-hidden shadow-2xl relative group">
              <img
                src={product.image || "https://via.placeholder.com/600"}
                alt={product.name}
                className="w-full h-full object-cover group-hover:scale-[1.03] transition duration-700 ease-in-out"
              />
            </div>
          </div>

          {/* DETAILS SECTION */}
          <div className="lg:col-span-5 flex flex-col justify-center">

            <p className="text-sm text-gray-500 mb-2 tracking-widest uppercase">
              {product.category}
            </p>

            <h1 className="text-4xl lg:text-5xl font-serif mb-4 text-gray-900 leading-tight">
              {product.name}
            </h1>

            <p className="text-2xl text-gray-800 mb-8 font-light">
              ${product.price}.00
            </p>

            <div className="bg-white p-8 shadow-sm mb-8">
              {/* COLOR */}
              <div className="mb-8">
                <p className="text-sm font-medium mb-3 uppercase tracking-wider text-gray-900">Color: <span className="text-gray-500">{selectedColor}</span></p>
                <div className="flex gap-4">
                  {[
                    { name: "Black", code: "#1a1a1a" },
                    { name: "Beige", code: "#e5e0d8" },
                    { name: "White", code: "#f9f9f9" }
                  ].map(color => (
                    <button
                      key={color.name}
                      onClick={() => setSelectedColor(color.name)}
                      className={`w-10 h-10 rounded-full border-2 transition-all duration-200 ${
                        selectedColor === color.name 
                          ? "border-gray-900 scale-110 shadow-md" 
                          : "border-transparent shadow-sm hover:scale-105"
                      }`}
                      style={{ backgroundColor: color.code }}
                      aria-label={color.name}
                    />
                  ))}
                </div>
              </div>

              {/* SIZE */}
              <div className="mb-8">
                <div className="flex justify-between items-end mb-3">
                  <p className="text-sm font-medium uppercase tracking-wider text-gray-900">Size</p>
                  <span className="text-xs text-gray-500 underline cursor-pointer hover:text-black">Size Guide</span>
                </div>
                <div className="grid grid-cols-4 gap-3">
                  {["S", "M", "L", "XL"].map(size => (
                    <button
                      key={size}
                      onClick={() => setSelectedSize(size)}
                      className={`py-3 text-sm tracking-wider transition-all duration-200 ${
                        selectedSize === size
                          ? "bg-gray-900 text-white shadow-md"
                          : "bg-gray-50 text-gray-800 border border-gray-200 hover:border-gray-900"
                      }`}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>

              {/* ADD TO CART */}
              <button
                onClick={addToCart}
                className="w-full bg-black text-white py-4 text-sm font-medium tracking-widest uppercase hover:bg-gray-800 transition transform hover:scale-[1.02] shadow-xl"
              >
                Add to Bag
              </button>
            </div>

            {/* DESCRIPTION */}
            <div className="prose prose-sm text-gray-600 border-t border-gray-200 pt-8">
              <h3 className="font-medium text-gray-900 uppercase tracking-widest text-xs mb-4">Product Details</h3>
              <p className="leading-relaxed">
                {product.description || "An essential piece for your curated wardrobe. Designed with impeccable attention to detail and crafted from the finest materials to ensure longevity and timeless elegance."}
              </p>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
}

export default ProductDetails;
